// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PuttyV2} from "../src/PuttyV2.sol";

contract InvMutTest is Test {
    PuttyV2 c;
    function setUp() public { c = new PuttyV2("", 0, address(this)); }

    function testFuzz_property(address to, uint256 id) public {
        vm.assume(to != address(0));
        id = bound(id, 1, type(uint256).max - 1);

        // Authorize the transfer away from the zero address (unminted ids have _ownerOf[id] == address(0)).
        vm.prank(address(0));
        c.setApprovalForAll(address(this), true);

        // Drive c through transferFrom: move the (hitherto nonexistent) id to a real recipient.
        bool transferOk;
        try c.transferFrom(address(0), to, id) {
            transferOk = true;
        } catch {
            transferOk = false;
        }
        assertTrue(transferOk, "transferFrom should succeed");

        // General rule: after a successful transferFrom to a nonzero recipient, the id is owned
        // by the recipient, so querying its URI must not revert.
        bool uriOk;
        try c.tokenURI(id) {
            uriOk = true;
        } catch {
            uriOk = false;
        }
        assertTrue(uriOk, "token must exist after transfer to a nonzero recipient");
    }
}
